pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 value, uint32 blockNum, uint32 warpSeconds) public {
        // ensure the call does not revert for other reasons: warp strictly forward
        uint256 past = c.pastBlockTime();
        vm.warp(block.timestamp + warpSeconds + 1 + past);
        vm.roll(blockNum);
        // exclude 10 ether: the reference requires exactly 10 ether, bug allows any value
        vm.assume(value != 10 ether);
        // restrict to a feasible ether amount
        bound(value, 0, 100 ether);
        address actor = makeAddr("actor");
        vm.deal(actor, value);
        bool ok;
        vm.prank(actor);
        try c.fallback{value: value}() { ok = true; } catch { ok = false; }
        // The reference enforces msg.value == 10 ether, so every non-10-ether call MUST revert.
        // The bug removes that require and allows such calls to succeed (as long as timestamp condition is met).
        assertTrue(!ok, "non-10-ether call did not revert");
    }
}

