pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockNumber) public {
        // Admissible domain: exactly 10 ether and blockNumber >= 0
        vm.assume(value == 10 ether);
        blockNumber = bound(blockNumber, 0, type(uint256).max);
        vm.roll(blockNumber);

        address sender = address(0x1234);
        vm.deal(sender, value);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: value}("");
        require(success, "call failed");

        // After every successful fallback call, the contract balance must be 0.
        // In the reference, if (block.number % 15 == 0) balance is transferred to sender,
        // otherwise balance remains 10 ether. But the invariant is actually: 
        // the contract never holds more than 10 ether after any call,
        // and if block.number % 15 == 0, balance must be 0.
        // However, the strongest invariant that holds for reference and breaks for bug is:
        // immediately after the call, if block.number % 15 == 0, balance is 0.
        // Let's refine: the reference always ends with 0 balance when the drain fires,
        // but the bug can accumulate multiple 10 ether deposits and then drain them all,
        // leaving a non-zero balance after the drain. But the drain sends the entire balance.
        // Actually, the drain in both versions sends address(this).balance, so after drain,
        // balance should be 0 in both. The difference is that the bug allows sending multiple times
        // before a drain, causing the drain to send more than 10 ether, but still balance becomes 0.
        // Wait, the prompt says "after a call to fallback() completes, the value of state variable fallback differs".
        // That's a typo; it means the state of the contract differs. The bug deletes the require(block.timestamp > pastBlockTime).
        // This allows multiple calls in the same block. With the reference, only one call per block is possible.
        // The invariant: pastBlockTime strictly increases after every successful call.
        // That was already tried and rejected? The prompt says "These approaches were already tried for this difference; do not repeat them:".
        // It lists exactly that invariant. So we must find a different invariant.
        // New invariant: The contract's balance is never greater than 10 ether immediately after a successful call.
        // In reference, because only one 10 ether deposit per block, and if block.number % 15 == 0 it drains, balance is 0 or 10.
        // In bug, you can deposit multiple times in same block, accumulating >10 ether, violating balance <= 10 ether.

        assertTrue(address(c).balance <= 10 ether);
    }
}

