pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 callCount) public {
        // Restrict callCount to a reasonable range for efficiency
        callCount = bound(callCount, 1, 10);

        // Ensure the contract has enough balance to handle multiple calls without reverting
        // We'll fund the contract before each call so msg.value == 10 ether can be met
        // Use a consistent caller for simplicity
        address caller = address(0x1234);
        vm.deal(caller, 1000 ether);

        // Wrap in try/catch to handle potential reverts; we only care about successful calls
        for (uint256 i = 0; i < callCount; i++) {
            vm.prank(caller);
            try c.fallback{value: 10 ether}() {
                // success
            } catch {
                // If a call reverts, stop and check the invariant after the last successful call
                break;
            }
        }

        // The reference contract only allows calls where block.timestamp > pastBlockTime.
        // In the fuzzer, block.timestamp only advances when vm.warp or vm.roll is used,
        // or by default between transactions in some setups. Since we do not warp,
        // block.timestamp remains constant throughout the loop.
        // Thus, in the reference, only the very first call succeeds; subsequent calls revert
        // because pastBlockTime is set to the current timestamp, making the require fail.
        // In the buggy version, all calls succeed.
        // The invariant: after the first successful call in a block (which is guaranteed by
        // the loop), the contract's balance modulo 10 ether must be 0, IF no transfer has
        // occurred (which depends on block.number).
        // But the invariant must hold for ALL inputs. We need a property that the reference
        // satisfies but the buggy one can violate.
        //
        // Property: If a fallback call succeeds, then either the contract's balance becomes 0
        // (if block.number % 15 == 0) OR the balance is exactly 10 ether * (number of successful
        // calls in this block) before the transfer check. But this depends on block.number.
        //
        // Simpler: In the reference, at most ONE call can succeed per block. Therefore,
        // after the loop, the total number of successful calls is exactly 1.
        // In the buggy, it can be many.
        // We can observe `pastBlockTime` to see if it was set: if it equals the current
        // block.timestamp (i.e., a call succeeded), then in the reference, exactly one call
        // succeeded, so the contract's balance, if not transferred, should be exactly 10 ether.
        // If transferred (on block.number % 15 == 0), balance should be 0.
        // But we cannot read the number of successful calls directly.
        //
        // Instead, use the fact that in the reference, pastBlockTime is strictly greater than
        // the previous pastBlockTime. Our test can check: if a call succeeds and the balance
        // is not zero (indicating no transfer happened), then the balance must be exactly
        // 10 ether. In the buggy, multiple calls can lead to balance > 10 ether while
        // pastBlockTime == block.timestamp.
        //
        // Let's assert: After a call that does not revert, if pastBlockTime == block.timestamp
        // (indicating the call succeeded), then the contract's balance is either 0 or exactly
        // 10 ether. The buggy contract can have balance = 20 ether (or more) when multiple
        // calls succeed in the same block and no transfer occurs.

        uint256 balance = address(c).balance;
        uint256 pbt = c.pastBlockTime();
        // Only check the invariant if a call actually succeeded (pbt == block.timestamp after success)
        if (pbt == block.timestamp) {
            // In the reference, balance is 0 or 10 ether.
            // In the buggy, it can be multiples of 10 ether > 10.
            assertTrue(balance == 0 || balance == 10 ether);
        } else {
            // No call succeeded, hence balance should be 0 (nothing deposited successfully).
            assertTrue(balance == 0);
        }
    }
}

