pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint8 numCalls) public {
        vm.assume(blockNum > 0);
        vm.assume(numCalls >= 1 && numCalls <= 5);
        vm.roll(blockNum);

        address caller = address(0xdead);
        vm.deal(caller, 100 ether);

        // Make numCalls calls, each in a separate block
        for (uint8 i = 0; i < numCalls; i++) {
            vm.roll(blockNum + i);
            vm.warp(block.timestamp + i);
            vm.prank(caller);
            (bool ok, ) = address(c).call{value: 10 ether}("");
            require(ok, "call failed");
        }

        // After the sequence, find a block where condition hits and trigger drain
        vm.roll(blockNum + 100);
        vm.warp(block.timestamp + 100);
        while (block.number % 15 != 0) {
            vm.roll(block.number + 1);
        }
        vm.prank(caller);
        (bool drainOk, ) = address(c).call{value: 10 ether}("");
        require(drainOk, "drain call failed");

        // After a drain-triggering call, the contract's balance must be exactly 0.
        // The buggy version allows repeated same-block calls earlier, accumulating
        // extra ETH that survives the drain, leaving the balance > 0.
        assertEq(address(c).balance, 0);
    }
}

